(function(){
  const KEY='nawaf-hq-v3';
  const $=(s,r=document)=>r.querySelector(s);
  const getState=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'null')}catch{return null}};
  const statusColor={READY:0x5ed7a5,IDLE:0x5ed7a5,WORKING:0xe0b75b,RESEARCHING:0x72a7ff,COLLABORATING:0xb58cff,REVIEWING:0xf0a85f,WAITING_FOR_NAWAF:0xd68157};
  const people=[
    {id:'sara',name:'سارة',role:'المدير العام AI',wing:'الإدارة العامة',a:-42},
    {id:'omar',name:'عمر',role:'التقنية والبحث',wing:'التقنية والبحث',a:42},
    {id:'lian',name:'ليان',role:'المنتج والتجربة',wing:'المنتج والتجربة',a:138},
    {id:'noura',name:'نورة',role:'الجودة والمراجعة',wing:'الجودة والمراجعة',a:222},
  ];

  function stateFor(id){const s=getState();return (s?.employees||[]).find(e=>e.id===id)||{status:'READY'}}
  function openPerson(id){if(typeof window.NawafHQ?.employeeView==='function')return window.NawafHQ.employeeView(id);if(id==='sara'&&window.NawafCompanyBoard?.open)return window.NawafCompanyBoard.open('company');}
  function mat(color,metal=.2,rough=.65){return new THREE.MeshStandardMaterial({color,metalness:metal,roughness:rough})}
  function box(scene,w,h,d,color,x,y,z,rot=0,metal=.15,rough=.7){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(color,metal,rough));m.position.set(x,y,z);m.rotation.y=rot;m.castShadow=true;m.receiveShadow=true;scene.add(m);return m}
  function cyl(scene,r,h,color,x,y,z,segments=48){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,segments),mat(color,.35,.45));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m}
  function addPlant(group,x,z,s=.8){const pot=new THREE.Mesh(new THREE.CylinderGeometry(.28,.35,.5,16),mat(0x382817,.15,.8));pot.position.set(x,.25,z);group.add(pot);for(let i=0;i<5;i++){const leaf=new THREE.Mesh(new THREE.SphereGeometry(.12,12,8),mat(0x173f2b,.05,.8));leaf.scale.set(.55,1.9,.5);leaf.rotation.z=(i-2)*.38;leaf.position.set(x+(i-2)*.08,.72+Math.abs(i-2)*.02,z);group.add(leaf)}}
  function addDesk(group,x,z,rot=0){const desk=new THREE.Group();desk.rotation.y=rot;desk.position.set(x,0,z);const top=new THREE.Mesh(new THREE.BoxGeometry(2.2,.18,.9),mat(0xc7b28d,.05,.5));top.position.y=.85;desk.add(top);[-.85,.85].forEach(px=>{const leg=new THREE.Mesh(new THREE.BoxGeometry(.12,.82,.12),mat(0x292929,.45,.45));leg.position.set(px,.42,0);desk.add(leg)});const screen=new THREE.Mesh(new THREE.BoxGeometry(.95,.58,.06),mat(0x0e1722,.55,.32));screen.position.set(0,1.25,-.18);desk.add(screen);const glow=new THREE.Mesh(new THREE.PlaneGeometry(.78,.41),new THREE.MeshBasicMaterial({color:0x346fa5,transparent:true,opacity:.62}));glow.position.set(0,1.25,-.215);glow.rotation.y=Math.PI;desk.add(glow);group.add(desk);return desk}
  function addRobot(group,p,x,z,rot=0){const st=stateFor(p.id);const c=statusColor[st.status]||statusColor.READY;const bot=new THREE.Group();bot.userData.employeeId=p.id;bot.position.set(x,0,z);bot.rotation.y=rot;const body=new THREE.Mesh(new THREE.CapsuleGeometry(.28,.48,7,14),mat(0xf0f2f5,.05,.35));body.position.y=.68;body.castShadow=true;bot.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.34,24,16),mat(0xf5f7fa,.05,.3));head.scale.y=.8;head.position.y=1.28;head.castShadow=true;bot.add(head);const face=new THREE.Mesh(new THREE.BoxGeometry(.48,.16,.045),mat(0x0b1018,.6,.2));face.position.set(0,1.28,-.285);bot.add(face);[-.12,.12].forEach(ex=>{const eye=new THREE.Mesh(new THREE.SphereGeometry(.035,12,8),new THREE.MeshBasicMaterial({color:c}));eye.position.set(ex,1.28,-.315);bot.add(eye)});const ring=new THREE.Mesh(new THREE.TorusGeometry(.34,.018,8,36),new THREE.MeshBasicMaterial({color:c,transparent:true,opacity:.75}));ring.rotation.x=Math.PI/2;ring.position.y=.38;bot.add(ring);const hit=new THREE.Mesh(new THREE.CylinderGeometry(.55,.55,1.8,16),new THREE.MeshBasicMaterial({transparent:true,opacity:0}));hit.position.y=.9;hit.userData.employeeId=p.id;bot.add(hit);group.add(bot);return {group:bot,status:st.status,baseY:0}}
  function addLabel(group,text,x,y,z){const c=document.createElement('canvas');c.width=512;c.height=96;const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='rgba(7,8,10,.78)';ctx.roundRect(4,4,504,88,18);ctx.fill();ctx.strokeStyle='rgba(213,178,108,.65)';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#f4ead7';ctx.font='600 31px Arial';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,256,48);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;const s=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthWrite:false}));s.position.set(x,y,z);s.scale.set(3.8,.72,1);group.add(s);return s}
  function addWing(scene,p,angleDeg){const a=THREE.MathUtils.degToRad(angleDeg),r=7.1,cx=Math.cos(a)*r,cz=Math.sin(a)*r;const g=new THREE.Group();g.rotation.y=-a+Math.PI/2;g.position.set(cx,0,cz);scene.add(g);const floor=new THREE.Mesh(new THREE.BoxGeometry(5.3,.16,4.4),mat(0xe8e2d7,.02,.9));floor.position.y=.05;floor.receiveShadow=true;g.add(floor);const back=new THREE.Mesh(new THREE.BoxGeometry(5.3,2.3,.14),mat(0xf2eee6,.02,.82));back.position.set(0,1.15,2.13);g.add(back);const side=new THREE.Mesh(new THREE.BoxGeometry(.14,2.3,4.35),mat(0xe8e4dc,.02,.85));side.position.set(-2.58,1.15,0);g.add(side);const glass=new THREE.Mesh(new THREE.BoxGeometry(2.5,1.05,.05),new THREE.MeshPhysicalMaterial({color:0x283b50,transparent:true,opacity:.42,roughness:.18,metalness:.15}));glass.position.set(.9,1.42,2.045);g.add(glass);addDesk(g,.55,.25,Math.PI);addDesk(g,-.9,-.85,Math.PI);addPlant(g,1.9,1.45,.8);addPlant(g,-2.1,1.25,.7);const robot=addRobot(g,p,.6,-.55,Math.PI);addLabel(g,p.wing,0,2.55,1.95);return robot}
  function init(){const office=$('.office');if(!office||office.dataset.office3d==='1'||!window.THREE)return;office.dataset.office3d='1';office.classList.add('hq-office-3d');office.innerHTML='<div class="hq3d-head"><div><span><i></i> LIVE 3D OFFICE</span><b>المقر التفاعلي</b><small>اضغط على أي روبوت لفتح مساحة الموظف</small></div><button id="hq3d-board">مجلس الشركة</button></div><div id="hq3d-stage"><div class="hq3d-loading">جاري تجهيز المقر…</div></div><div class="hq3d-foot"><span>● الحالات مربوطة بالعمل الحقيقي</span><small>اسحب بالماوس لتحريك زاوية النظر</small></div>';
    $('#hq3d-board',office).onclick=()=>window.NawafCompanyBoard?.open?.('company');
    const host=$('#hq3d-stage',office);const scene=new THREE.Scene();scene.background=new THREE.Color(0x07101a);scene.fog=new THREE.Fog(0x07101a,17,31);
    const camera=new THREE.PerspectiveCamera(34,host.clientWidth/host.clientHeight,.1,100);camera.position.set(14,15,18);camera.lookAt(0,0,0);
    const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(host.clientWidth,host.clientHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;host.innerHTML='';host.appendChild(renderer.domElement);
    scene.add(new THREE.HemisphereLight(0x9bbcff,0x20170d,2.1));const sun=new THREE.DirectionalLight(0xffe1b0,3.2);sun.position.set(4,14,7);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-20;sun.shadow.camera.right=20;sun.shadow.camera.top=20;sun.shadow.camera.bottom=-20;scene.add(sun);const blue=new THREE.PointLight(0x4e7dff,40,18,2);blue.position.set(0,3.8,0);scene.add(blue);
    const base=new THREE.Mesh(new THREE.CylinderGeometry(12.8,13.5,.5,64),mat(0x11161d,.45,.48));base.position.y=-.25;base.receiveShadow=true;scene.add(base);const garden=new THREE.Mesh(new THREE.RingGeometry(10.9,13,64),mat(0x0f2b22,.02,.95));garden.rotation.x=-Math.PI/2;garden.position.y=.015;scene.add(garden);
    for(let i=0;i<18;i++){const a=i/18*Math.PI*2,r=11.6+(i%3)*.28;const p=new THREE.Mesh(new THREE.SphereGeometry(.18+.07*(i%2),10,8),mat(0x1e5639,.02,.9));p.scale.y=1.8;p.position.set(Math.cos(a)*r,.35,Math.sin(a)*r);scene.add(p)}
    const hub=cyl(scene,3.05,.3,0x18202b,0,.15,0,64);const hubRing=new THREE.Mesh(new THREE.TorusGeometry(2.4,.05,12,64),new THREE.MeshBasicMaterial({color:0x4f7cff}));hubRing.rotation.x=Math.PI/2;hubRing.position.y=.38;scene.add(hubRing);const core=new THREE.Mesh(new THREE.SphereGeometry(.82,32,24),new THREE.MeshPhysicalMaterial({color:0x5e6dff,emissive:0x182a7a,emissiveIntensity:2.2,metalness:.15,roughness:.08,transparent:true,opacity:.72}));core.position.y=1.15;scene.add(core);const coreWire=new THREE.Mesh(new THREE.SphereGeometry(1.12,20,14),new THREE.MeshBasicMaterial({color:0x73a0ff,wireframe:true,transparent:true,opacity:.28}));coreWire.position.y=1.15;scene.add(coreWire);addLabel(scene,'NAWAF HQ · COMMAND CORE',0,2.9,0);
    const bots=people.map(p=>addWing(scene,p,p.a));
    const council={id:'council',name:'مجلس الشركة',role:'المناقشات والقرارات',wing:'مجلس الشركة',a:90};addWing(scene,council,90);const analytics={id:'analytics',name:'التحليلات',role:'لوحة المتابعة',wing:'التحليلات',a:270};addWing(scene,analytics,270);
    const ray=new THREE.Raycaster(),mouse=new THREE.Vector2();renderer.domElement.addEventListener('click',e=>{const r=renderer.domElement.getBoundingClientRect();mouse.x=((e.clientX-r.left)/r.width)*2-1;mouse.y=-((e.clientY-r.top)/r.height)*2+1;ray.setFromCamera(mouse,camera);const hits=ray.intersectObjects(scene.children,true);const target=hits.find(h=>h.object.userData.employeeId);if(target)openPerson(target.object.userData.employeeId)});
    let drag=false,lastX=0,theta=0;renderer.domElement.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;renderer.domElement.setPointerCapture(e.pointerId)});renderer.domElement.addEventListener('pointerup',()=>drag=false);renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;theta+=(e.clientX-lastX)*.004;lastX=e.clientX;camera.position.x=Math.sin(theta+.66)*22;camera.position.z=Math.cos(theta+.66)*22;camera.lookAt(0,.7,0)});
    const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();core.rotation.y=t*.32;coreWire.rotation.y=-t*.18;hubRing.rotation.z=t*.06;bots.forEach((b,i)=>{const active=!['READY','IDLE'].includes(b.status);b.group.position.y=Math.sin(t*(active?3.3:1.5)+i)*(.035+(active?.035:0));if(active)b.group.rotation.y+=Math.sin(t*4+i)*.0007});renderer.render(scene,camera)}animate();
    const resize=new ResizeObserver(()=>{if(!host.clientWidth||!host.clientHeight)return;camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();renderer.setSize(host.clientWidth,host.clientHeight)});resize.observe(host);
  }
  function boot(){if(window.THREE)init();else setTimeout(boot,120)}
  document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();
  const mo=new MutationObserver(()=>{const o=$('.office');if(o&&!o.dataset.office3d)setTimeout(boot,80)});mo.observe(document.documentElement,{childList:true,subtree:true});
})();